(()=>{function wire(){document.querySelectorAll('[data-newsletter-form]').forEach(f=>{if(f.dataset.wired)return;f.dataset.wired='1';f.addEventListener('submit',e=>{e.preventDefault();const src=String(new FormData(f).get('source')||'legacy').slice(0,80);window.JHAnalytics?.track('newsletter_cta_click',{placement:src});location.assign('/newsletter/?source='+encodeURIComponent(src)+'&placement=legacy-form')})})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',wire,{once:true}):wire()})();
